  /// Organization name for identification and display purposes.
  name String

  /// Brief description of the organization's purpose or industry.
  description String?

  /// URI to the organization's logo image file for branding.
  logo_image_uri String? @db.VarChar(80000)

  /// Current operational status of the organization. Values: 'active' - fully
