  // spellchecker: ignore-next-line
  role       erp_time_track_custom_roles? @relation(fields: [erp_time_track_custom_role_id], references: [id], onDelete: Cascade, map: "erp_time_track_employee_snapshots_erp_time_track_custo_faa89900")
  // spellchecker: ignore-next-line
