schemas.schema-04-projects.prisma:
/// Main project entity representing work initiatives within an organization.
///
/// Projects organize work efforts with budgets, timelines, and visual
/// identification. Each project has a status lifecycle (active, archived,
/// completed) and can contain multiple tasks. Projects are assigned to
/// employees through project memberships with specific roles (member or
/// project-lead).
///
/// Budget hours track estimated vs actual time consumption, while start and
/// end dates define the project timeline. Color codes provide visual
/// identification in user interfaces. Projects are strictly scoped to their
/// parent organization ensuring multi-tenancy data isolation.
///
/// Related entities: {@link erp_time_track_organizations} (parent
/// organization), {@link erp_time_track_project_memberships} (employee
/// assignments), {@link erp_time_track_tasks} (contained work items).
///
/// @namespace Projects
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model erp_time_track_projects {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Parent organization that owns this project. {@link
  /// erp_time_track_organizations.id}.
  organization_id String @db.Uuid

  /// Project name for identification and reference.
  name String

  /// Detailed project description explaining purpose, scope, and objectives.
  description String?

  /// Hexadecimal color code (e.g., #FF5733) for visual identification in user
  /// interfaces.
  color_code String

  /// Current lifecycle status: 'active' (accepting time entries), 'archived'
  /// (historical reference only), or 'completed' (finished work).
  status String

  /// Total estimated hours budgeted for the project. Null indicates no budget
  /// tracking.
  budget_hours Float? @db.DoublePrecision

  /// Planned project start date for timeline reference.
  start_date DateTime? @db.Timestamptz

  /// Planned project end date for timeline reference.
  end_date DateTime? @db.Timestamptz

  /// Timestamp when the project was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the project was last modified.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the project was soft-deleted. Null indicates active record.
  deleted_at DateTime? @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  organization erp_time_track_organizations @relation(fields: [organization_id], references: [id], onDelete: Cascade)

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  snapshots          erp_time_track_project_snapshots[]
  tasks              erp_time_track_tasks[]
  projectMemberships erp_time_track_project_memberships[]
  timelogs           erp_time_track_timelogs[]
  timers             erp_time_track_timers[]
  projectTimeTotals  erp_time_track_project_time_totals[]

  //----
  // INDEXES
  //----
  @@unique([organization_id, name])
  @@index([organization_id, status])
  @@index([organization_id, start_date])
  @@index([organization_id, end_date])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Point-in-time snapshots of project data for audit trail and historical
