  // spellchecker: ignore-next-line
  @@index([erp_time_track_member_id, created_at], map: "erp_time_track_task_histories_erp_time_track_member_id_1a166f0e")
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

